#!/usr/bin/env python3
# -*- coding: utf-8 -*-
from pathlib import Path
import shutil, subprocess, sys, tempfile, time

ROOT=Path.cwd().resolve()
if not (ROOT/'app/build.gradle.kts').exists(): raise SystemExit('❌ شغّل الملف من جذر المستودع')
def read(rel): return (ROOT/rel).read_text(encoding='utf-8')
def write(rel,s): (ROOT/rel).write_text(s,encoding='utf-8')
def replace_once(rel,old,new,label):
    s=read(rel)
    if new in s: print('ℹ️ '+label+': مطبق مسبقًا'); return
    if old not in s: raise SystemExit('❌ لم أجد موضع التعديل: '+label)
    write(rel,s.replace(old,new,1)); print('✅ '+label)
def replace_all(rel,pairs,label):
    s=read(rel); o=s
    for a,b in pairs: s=s.replace(a,b)
    if s!=o: write(rel,s); print('✅ '+label)
    else: print('ℹ️ '+label+': لا تغيير')

